import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import { motion } from 'framer-motion';
import { 
  MapPin, 
  Package, 
  Clock, 
  Truck, 
  Navigation, 
  Map, 
  Route,
  Cloud,
  Users,
  AlertTriangle,
  TrendingUp,
  UserCheck,
  X,
  CheckCircle,
  AlertCircle,
  Star,
  ArrowRight,
  Phone,
  Mail,
  RefreshCw,
  Zap,
  BarChart3,
  Activity
} from 'lucide-react';
import * as L from 'leaflet';
import 'leaflet/dist/leaflet.css';

interface Employee {
  id: string;
  name: string;
  email: string;
  phone: string;
  status: string;
  currentLocation: { lat: number; lng: number };
  vehicleType: string;
  maxOrders: number;
  currentOrders: number;
  onBreak: boolean;
  skills: string[];
  rating: number;
  orders?: Order[];
}

interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone: string;
  address: string;
  coordinates: { lat: number; lng: number };
  assignedEmployeeId: string;
  status: string;
  priority: string;
  orderTime: string;
  estimatedDeliveryTime: string;
  actualDeliveryTime: string | null;
  delayStatus: string;
  delayReason: string | null;
  weatherImpact: boolean;
  trafficImpact: boolean;
  items: Array<{ name: string; weight: string; dimensions: string }>;
  value: number;
  paymentMethod: string;
}

interface WeatherData {
  location: string;
  temperature: number;
  condition: string;
  humidity: number;
  windSpeed: number;
  visibility: number;
  forecast?: Array<{ time: string; temp: number; condition: string }>;
}

interface Recommendation {
  type: string;
  action: string;
  priority: string;
  description: string;
}

const EmployeePortal: React.FC = () => {
  const [employeeId, setEmployeeId] = useState('');
  const [password, setPassword] = useState('');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [employee, setEmployee] = useState<Employee | null>(null);
  const [orders, setOrders] = useState<Order[]>([]);
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [recommendations, setRecommendations] = useState<Recommendation[]>([]);
  const [availableEmployees, setAvailableEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showReassignModal, setShowReassignModal] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [selectedEmployee, setSelectedEmployee] = useState('');
  const mapRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<L.Map | null>(null);

  const fetchEmployeeData = async () => {
    if (!employee) return;

    try {
      const response = await axios.get(`http://localhost:5000/api/employees/${employee.id}`);
      const employeeData = response.data.data;
      setEmployee(employeeData);
      setOrders(employeeData.orders || []);
      generateRecommendations(employeeData, employeeData.orders || []);
    } catch (err) {
      console.error('Failed to fetch employee data:', err);
    }
  };

  useEffect(() => {
    if (isLoggedIn && employee) {
      fetchEmployeeData();
      
      const fetchWeather = async () => {
        try {
          const response = await axios.get('http://localhost:5000/api/logistics/weather/delhi');
          setWeather(response.data.data);
        } catch (err) {
          console.error('Failed to fetch weather:', err);
        }
      };
      
      fetchWeather();
    }
  }, [isLoggedIn, employee, fetchEmployeeData]);

  const handleLogin = async () => {
    if (!employeeId.trim() || !password.trim()) {
      setError('Please enter both Employee ID and Password');
      return;
    }

    setLoading(true);
    setError('');
    try {
      const response = await axios.post('http://localhost:5000/api/employees/login', {
        employeeId,
        password
      });

      if (response.data.success) {
        setEmployee(response.data.data);
        setIsLoggedIn(true);
      }
    } catch (err: any) {
      setError(err.response?.data?.error || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  const fetchAvailableEmployees = async (orderId: string) => {
    try {
      const response = await axios.get(`http://localhost:5000/api/employees/available/${orderId}`);
      setAvailableEmployees(response.data.data);
    } catch (err) {
      console.error('Failed to fetch available employees:', err);
    }
  };

  const handleReassign = async () => {
    if (!selectedOrder || !selectedEmployee) return;

    setLoading(true);
    try {
      const response = await axios.put(`http://localhost:5000/api/orders/${selectedOrder.id}/reassign`, {
        newEmployeeId: selectedEmployee
      });

      if (response.data.success) {
        await fetchEmployeeData();
        setShowReassignModal(false);
        setSelectedOrder(null);
        setSelectedEmployee('');
        alert('Order reassigned successfully!');
      }
    } catch (err: any) {
      alert(err.response?.data?.error || 'Failed to reassign order');
    } finally {
      setLoading(false);
    }
  };

  const notifyCustomer = async (orderId: string) => {
    try {
      // Simulate customer notification
      alert(`Customer notified about order ${orderId} status update`);
    } catch (err) {
      console.error('Failed to notify customer:', err);
    }
  };

  const generateRecommendations = (employee: Employee, orders: Order[]) => {
    const recs: Recommendation[] = [];

    // Check for overload
    if (orders.length >= employee.maxOrders) {
      recs.push({
        type: 'overload',
        action: 'Reassign orders',
        priority: 'high',
        description: 'Employee is overloaded. Consider reassigning some orders to optimize delivery times.'
      });
    }

    // Check for weather-impacted orders
    const weatherImpactedOrders = orders.filter(order => order.weatherImpact);
    if (weatherImpactedOrders.length > 0) {
      recs.push({
        type: 'weather',
        action: 'Delay or reroute',
        priority: 'high',
        description: 'Weather conditions are impacting deliveries. Consider delaying or rerouting affected orders.'
      });
    }

    // Check for traffic-impacted orders
    const trafficImpactedOrders = orders.filter(order => order.trafficImpact);
    if (trafficImpactedOrders.length > 0) {
      recs.push({
        type: 'traffic',
        action: 'Optimize routes',
        priority: 'medium',
        description: 'Heavy traffic detected. Consider optimizing routes to avoid congestion.'
      });
    }

    setRecommendations(recs);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'delivered': return 'status-on-time';
      case 'in_transit': return 'status-in-progress';
      case 'delayed': return 'status-delayed';
      case 'pending': return 'status-in-progress';
      default: return 'status-in-progress';
    }
  };

  const formatDateTime = (dateString: string) => {
    return new Date(dateString).toLocaleString('en-IN', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  useEffect(() => {
    if (employee && orders.length > 0 && mapRef.current && !mapInstanceRef.current) {
      // Initialize map centered on employee location
      const map = L.map(mapRef.current).setView([employee.currentLocation.lat, employee.currentLocation.lng], 12);
      
      // Add OpenStreetMap tiles
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap contributors'
      }).addTo(map);

      // Add employee location marker
      const employeeIcon = L.divIcon({
        html: '🚚',
        iconSize: [30, 30],
        className: 'custom-div-icon'
      });
      
      L.marker([employee.currentLocation.lat, employee.currentLocation.lng], { icon: employeeIcon })
        .addTo(map)
        .bindPopup(`<b>Your Location</b><br>${employee.name}`)
        .openPopup();

      // Add markers for all assigned orders
      orders.forEach((order, index) => {
        const orderIcon = L.divIcon({
          html: order.priority === 'express' ? '⚡' : '📦',
          iconSize: [30, 30],
          className: 'custom-div-icon'
        });
        
        L.marker([order.coordinates.lat, order.coordinates.lng], { icon: orderIcon })
          .addTo(map)
          .bindPopup(`
            <b>${order.id}</b><br>
            Customer: ${order.customerName}<br>
            Status: ${order.status.replace('_', ' ').toUpperCase()}<br>
            Priority: ${order.priority.toUpperCase()}<br>
            Address: ${order.address}
          `);

        // Draw route line from employee to each order
        const routeCoordinates = [
          [employee.currentLocation.lat, employee.currentLocation.lng],
          [order.coordinates.lat, order.coordinates.lng]
        ];
        
        const routeColor = order.priority === 'express' ? 'red' : 
                          order.status === 'delayed' ? 'orange' : 'blue';
        
        (L.polyline as any)(routeCoordinates, {
          color: routeColor,
          weight: order.priority === 'express' ? 4 : 3,
          opacity: 0.7,
          dashArray: order.status === 'delayed' ? '5, 5' : '10, 10'
        }).addTo(map);
      });

      mapInstanceRef.current = map;

      return () => {
        if (mapInstanceRef.current) {
          mapInstanceRef.current.remove();
          mapInstanceRef.current = null;
        }
      };
    }
  }, [employee, orders]);

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
        {/* Navigation */}
        <motion.nav 
          initial={{ y: -100 }}
          animate={{ y: 0 }}
          className="fixed top-0 left-0 right-0 z-50 bg-white/80 backdrop-blur-lg border-b border-gray-200"
        >
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between items-center h-16">
              <div className="flex items-center space-x-2">
                <Truck className="w-8 h-8 text-blue-600" />
                <span className="text-xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">
                  Smart Logistics
                </span>
                <span className="text-sm text-gray-500 ml-2">Employee Portal</span>
              </div>
              <div className="hidden md:flex space-x-8">
                <Link to="/" className="text-gray-700 hover:text-blue-600 transition-colors font-medium">Home</Link>
                <Link to="/customer" className="text-gray-700 hover:text-blue-600 transition-colors font-medium">Customer Portal</Link>
                <Link to="/employee" className="text-blue-600 font-semibold">Employee Portal</Link>
              </div>
            </div>
          </div>
        </motion.nav>

        {/* Main Content */}
        <div className="pt-16 min-h-screen flex items-center justify-center px-4">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="w-full max-w-md"
          >
            <div className="bg-white rounded-2xl shadow-xl p-8">
              <div className="text-center mb-8">
                <div className="w-16 h-16 bg-gradient-to-r from-blue-600 to-purple-600 rounded-full flex items-center justify-center mx-auto mb-4">
                  <UserCheck className="w-8 h-8 text-white" />
                </div>
                <h2 className="text-2xl font-bold text-gray-900 mb-2">Employee Login</h2>
                <p className="text-gray-600">Access your delivery dashboard</p>
              </div>

              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Employee ID</label>
                  <input
                    type="text"
                    value={employeeId}
                    onChange={(e) => setEmployeeId(e.target.value)}
                    placeholder="Enter your Employee ID"
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Password</label>
                  <input
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="Enter your password"
                    onKeyPress={(e) => e.key === 'Enter' && handleLogin()}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
                  />
                </div>

                {error && (
                  <motion.div
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg flex items-center"
                  >
                    <AlertCircle className="w-5 h-5 mr-2" />
                    {error}
                  </motion.div>
                )}

                <motion.button
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  onClick={handleLogin} 
                  disabled={loading} 
                  className="w-full bg-gradient-to-r from-blue-600 to-purple-600 text-white font-semibold py-3 px-6 rounded-lg hover:from-blue-700 hover:to-purple-700 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center"
                >
                  {loading ? (
                    <>
                      <RefreshCw className="w-5 h-5 mr-2 animate-spin" />
                      Logging in...
                    </>
                  ) : (
                    <>
                      <ArrowRight className="w-5 h-5 mr-2" />
                      Login
                    </>
                  )}
                </motion.button>
              </div>

              <div className="mt-6 p-4 bg-gray-50 rounded-lg">
                <p className="text-sm font-medium text-gray-700 mb-3">Quick Access - Employee IDs:</p>
                <div className="flex flex-wrap gap-2 mb-3">
                  {['EMP001', 'EMP002', 'EMP003', 'EMP004', 'EMP005'].map((id) => (
                    <motion.button
                      key={id}
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      onClick={() => setEmployeeId(id)}
                      className="px-3 py-1 bg-white border border-gray-300 rounded-lg text-sm font-medium hover:bg-blue-50 hover:border-blue-300 transition-all"
                    >
                      {id}
                    </motion.button>
                  ))}
                </div>
                <p className="text-xs text-gray-500">Default password: <code className="bg-gray-200 px-1 py-0.5 rounded">password123</code></p>
              </div>
            </div>
          </motion.div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
      {/* Navigation */}
      <motion.nav 
        initial={{ y: -100 }}
        animate={{ y: 0 }}
        className="fixed top-0 left-0 right-0 z-50 bg-white/80 backdrop-blur-lg border-b border-gray-200"
      >
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center space-x-2">
              <Truck className="w-8 h-8 text-blue-600" />
              <span className="text-xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">
                Smart Logistics
              </span>
              <span className="text-sm text-gray-500 ml-2">Employee Portal</span>
            </div>
            <div className="hidden md:flex space-x-8">
              <Link to="/" className="text-gray-700 hover:text-blue-600 transition-colors font-medium">Home</Link>
              <Link to="/customer" className="text-gray-700 hover:text-blue-600 transition-colors font-medium">Customer Portal</Link>
              <Link to="/employee" className="text-blue-600 font-semibold">Employee Portal</Link>
              <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => {
                  setIsLoggedIn(false);
                  setEmployee(null);
                  setOrders([]);
                  setEmployeeId('');
                  setPassword('');
                }}
                className="text-red-600 hover:text-red-700 font-medium transition-colors"
              >
                Logout
              </motion.button>
            </div>
          </div>
        </div>
      </motion.nav>

      {/* Main Content */}
      <div className="pt-16 px-4 sm:px-6 lg:px-8 max-w-7xl mx-auto">
        {/* Employee Info */}
        <motion.section
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="py-12"
        >
          <div className="bg-white rounded-2xl shadow-lg p-8 mb-8">
            <div className="flex items-center mb-6">
              <div className="w-12 h-12 bg-gradient-to-r from-blue-600 to-purple-600 rounded-full flex items-center justify-center mr-4">
                <UserCheck className="w-6 h-6 text-white" />
              </div>
              <h2 className="text-2xl font-bold text-gray-900">Employee Information</h2>
            </div>
            
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="space-y-4">
                <h3 className="font-semibold text-gray-900 mb-3 flex items-center">
                  <UserCheck className="w-4 h-4 mr-2 text-blue-600" />
                  Personal Details
                </h3>
                <div className="space-y-3">
                  <div className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                    <span className="text-sm text-gray-600">Name</span>
                    <span className="font-medium text-gray-900">{employee?.name}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                    <span className="text-sm text-gray-600">ID</span>
                    <span className="font-medium text-gray-900">{employee?.id}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                    <span className="text-sm text-gray-600">Phone</span>
                    <span className="font-medium text-gray-900">{employee?.phone}</span>
                  </div>
                </div>
              </div>
              
              <div className="space-y-4">
                <h3 className="font-semibold text-gray-900 mb-3 flex items-center">
                  <Truck className="w-4 h-4 mr-2 text-green-600" />
                  Work Status
                </h3>
                <div className="space-y-3">
                  <div className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                    <span className="text-sm text-gray-600">Vehicle</span>
                    <span className="font-medium text-gray-900">{employee?.vehicleType}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                    <span className="text-sm text-gray-600">Status</span>
                    <span className={`px-3 py-1 rounded-full text-xs font-semibold ${
                      employee?.status === 'active' ? 'bg-green-100 text-green-700' :
                      employee?.status === 'busy' ? 'bg-yellow-100 text-yellow-700' :
                      'bg-gray-100 text-gray-700'
                    }`}>
                      {employee?.status}
                    </span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                    <span className="text-sm text-gray-600">On Break</span>
                    <span className={`px-3 py-1 rounded-full text-xs font-semibold ${
                      employee?.onBreak ? 'bg-orange-100 text-orange-700' : 'bg-green-100 text-green-700'
                    }`}>
                      {employee?.onBreak ? 'Yes' : 'No'}
                    </span>
                  </div>
                </div>
              </div>
              
              <div className="space-y-4">
                <h3 className="font-semibold text-gray-900 mb-3 flex items-center">
                  <BarChart3 className="w-4 h-4 mr-2 text-purple-600" />
                  Performance
                </h3>
                <div className="space-y-3">
                  <div className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                    <span className="text-sm text-gray-600">Current Orders</span>
                    <span className="font-medium text-gray-900">{employee?.currentOrders}/{employee?.maxOrders}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                    <span className="text-sm text-gray-600">Rating</span>
                    <div className="flex items-center">
                      <Star className="w-4 h-4 text-yellow-500 mr-1" />
                      <span className="font-medium text-gray-900">{employee?.rating}</span>
                    </div>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                    <span className="text-sm text-gray-600">Skills</span>
                    <span className="font-medium text-gray-900 text-sm">{employee?.skills?.join(', ')}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </motion.section>

        {/* Orders List */}
        <motion.section
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.1 }}
          className="py-12"
        >
          <div className="bg-white rounded-2xl shadow-lg p-8 mb-8">
            <div className="flex items-center justify-between mb-6">
              <div className="flex items-center">
                <div className="w-12 h-12 bg-gradient-to-r from-green-600 to-emerald-600 rounded-full flex items-center justify-center mr-4">
                  <Package className="w-6 h-6 text-white" />
                </div>
                <h2 className="text-2xl font-bold text-gray-900">Assigned Orders</h2>
              </div>
              <div className="flex items-center space-x-2">
                <span className="px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-sm font-semibold">
                  {orders.length} Active
                </span>
              </div>
            </div>
            
            {orders.length === 0 ? (
              <div className="text-center py-12">
                <Package className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                <h3 className="text-lg font-semibold text-gray-900 mb-2">No orders assigned</h3>
                <p className="text-gray-600">You'll see your assigned orders here when they become available.</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <div className="min-w-full">
                  {orders.map((order, index) => (
                    <motion.div
                      key={order.id}
                      initial={{ opacity: 0, x: -20 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ duration: 0.3, delay: index * 0.1 }}
                      className="border border-gray-200 rounded-xl p-6 mb-4 hover:shadow-lg transition-all"
                    >
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <div className="flex items-center mb-3">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center mr-3 ${
                              order.priority === 'express' ? 'bg-red-100' :
                              order.priority === 'premium' ? 'bg-purple-100' :
                              'bg-gray-100'
                            }`}>
                              {order.priority === 'express' ? '⚡' : 
                               order.priority === 'premium' ? '🔥' : '📦'}
                            </div>
                            <div>
                              <h4 className="font-semibold text-gray-900">{order.id}</h4>
                              <p className="text-sm text-gray-600">{order.customerName}</p>
                            </div>
                          </div>
                          
                          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                            <div className="flex items-center text-sm">
                              <Clock className="w-4 h-4 mr-2 text-gray-400" />
                              <span className="text-gray-600">Est. Delivery: </span>
                              <span className="font-medium text-gray-900 ml-1">
                                {formatDateTime(order.estimatedDeliveryTime)}
                              </span>
                            </div>
                            <div className="flex items-center text-sm">
                              <MapPin className="w-4 h-4 mr-2 text-gray-400" />
                              <span className="text-gray-600 truncate max-w-xs">{order.address}</span>
                            </div>
                            <div className="flex items-center text-sm">
                              <Package className="w-4 h-4 mr-2 text-gray-400" />
                              <span className="text-gray-600">{order.items?.length || 0} items</span>
                            </div>
                          </div>
                          
                          <div className="flex items-center space-x-3">
                            <span className={`px-3 py-1 rounded-full text-xs font-semibold ${
                              order.status === 'delivered' ? 'bg-green-100 text-green-700' :
                              order.status === 'in_transit' ? 'bg-blue-100 text-blue-700' :
                              order.status === 'delayed' ? 'bg-red-100 text-red-700' :
                              'bg-yellow-100 text-yellow-700'
                            }`}>
                              {order.status.replace('_', ' ').toUpperCase()}
                            </span>
                            <span className={`px-3 py-1 rounded-full text-xs font-semibold ${
                              order.priority === 'express' ? 'bg-red-100 text-red-700' :
                              order.priority === 'premium' ? 'bg-purple-100 text-purple-700' :
                              'bg-gray-100 text-gray-700'
                            }`}>
                              {order.priority.toUpperCase()}
                            </span>
                          </div>
                        </div>
                        
                        <div className="flex space-x-2 ml-4">
                          <motion.button
                            whileHover={{ scale: 1.05 }}
                            whileTap={{ scale: 0.95 }}
                            onClick={() => notifyCustomer(order.id)}
                            className="p-2 bg-blue-100 text-blue-700 rounded-lg hover:bg-blue-200 transition-colors"
                            title="Notify Customer"
                          >
                            <Phone className="w-4 h-4" />
                          </motion.button>
                          <motion.button
                            whileHover={{ scale: 1.05 }}
                            whileTap={{ scale: 0.95 }}
                            onClick={() => {
                              setSelectedOrder(order);
                              setShowReassignModal(true);
                              fetchAvailableEmployees(order.id);
                            }}
                            className="p-2 bg-orange-100 text-orange-700 rounded-lg hover:bg-orange-200 transition-colors"
                            title="Reassign Order"
                          >
                            <RefreshCw className="w-4 h-4" />
                          </motion.button>
                        </div>
                      </div>
                    </motion.div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </motion.section>

        {/* Weather Information */}
        {weather && (
          <div className="weather-info">
            <h3>🌦️ Weather Information</h3>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: '1rem' }}>
              <div>
                <p><strong>Location:</strong> {weather.location}</p>
                <p><strong>Temperature:</strong> {weather.temperature}°C</p>
              </div>
              <div>
                <p><strong>Condition:</strong> {weather.condition}</p>
                <p><strong>Humidity:</strong> {weather.humidity}%</p>
              </div>
              <div>
                <p><strong>Wind Speed:</strong> {weather.windSpeed} km/h</p>
                <p><strong>Visibility:</strong> {weather.visibility} km</p>
              </div>
            </div>
            {weather.forecast && (
              <div style={{ marginTop: '1rem' }}>
                <h4>Hourly Forecast:</h4>
                <div style={{ display: 'flex', gap: '1rem', overflowX: 'auto' }}>
                  {weather.forecast.map((hour, index) => (
                    <div key={index} style={{ textAlign: 'center', padding: '0.5rem', backgroundColor: 'rgba(255,255,255,0.1)', borderRadius: '5px' }}>
                      <p style={{ fontSize: '0.875rem' }}>{hour.time}</p>
                      <p style={{ fontWeight: 'bold' }}>{hour.temp}°C</p>
                      <p style={{ fontSize: '0.75rem' }}>{hour.condition}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {/* Map Container */}
        <div className="card">
          <h3>🗺️ Route Map</h3>
          <div 
            ref={mapRef} 
            className="map-container" 
            style={{ height: '400px', width: '100%', borderRadius: '8px' }}
          >
            {(!employee || orders.length === 0) && (
              <div style={{ 
                height: '100%', 
                display: 'flex', 
                alignItems: 'center', 
                justifyContent: 'center',
                backgroundColor: '#f8f9fa',
                color: '#666'
              }}>
                <div style={{ textAlign: 'center' }}>
                  <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>🗺️</div>
                  <p>Login and check assigned orders to see route map</p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Solutions Section */}
        <div className="solutions-section">
          <h3>⚠️ Solutions & Recommendations</h3>
          {recommendations.length === 0 ? (
            <p>No immediate issues detected. All systems operating normally.</p>
          ) : (
            <div style={{ display: 'grid', gap: '1rem' }}>
              {recommendations.map((rec, index) => (
                <div key={index} className={`alert alert-${rec.priority === 'high' ? 'danger' : 'warning'}`}>
                  <h4>{rec.action}</h4>
                  <p>{rec.description}</p>
                  <p><strong>Priority:</strong> {rec.priority.toUpperCase()}</p>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Reassign Modal */}
      {showReassignModal && selectedOrder && (
        <div className="modal-overlay">
          <div className="modal">
            <h3>Reassign Order {selectedOrder.id}</h3>
            <div className="form-group">
              <label>Select Available Employee</label>
              <select
                value={selectedEmployee}
                onChange={(e) => setSelectedEmployee(e.target.value)}
              >
                <option value="">Choose an employee...</option>
                {availableEmployees.map((emp) => (
                  <option key={emp.id} value={emp.id}>
                    {emp.name} ({emp.id}) - {emp.currentOrders}/{emp.maxOrders} orders
                  </option>
                ))}
              </select>
            </div>
            <div style={{ display: 'flex', gap: '1rem', justifyContent: 'flex-end' }}>
              <button className="btn btn-secondary" onClick={() => setShowReassignModal(false)}>
                Cancel
              </button>
              <button className="btn" onClick={handleReassign} disabled={loading || !selectedEmployee}>
                {loading ? 'Processing...' : 'Reassign Order'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default EmployeePortal;
